-- ============================================================
-- NCV65全面预算系统 - 完整建表脚本及测试数据
-- 数据库：达梦DM8 (Oracle兼容)  Schema：REDACTED
-- 包含5大模块所有表：budgetControl, budgetAnalysis, advancedFeatures, budgetSystem, systemIntegration
-- 每表20条测试数据
-- ============================================================

-- ============================================================
-- 模块1: 预算控制管理 (budgetControl)
-- ============================================================

-- 1.1 预算执行表
CREATE TABLE "REDACTED"."TBL_BUDGET_EXECUTION" (
    "EXECUTION_ID"      VARCHAR2(64) NOT NULL,
    "EXECUTION_CODE"    VARCHAR2(100),
    "BUDGET_ID"         VARCHAR2(64),
    "BUSINESS_DOC_ID"   VARCHAR2(64),
    "BUSINESS_DOC_TYPE" VARCHAR2(50),
    "EXECUTION_AMOUNT"  NUMBER(20,2) DEFAULT 0,
    "EXECUTION_DATE"    DATE,
    "EXECUTION_TIME"    TIMESTAMP(6),
    "EXECUTION_TYPE"    VARCHAR2(50),
    "EXECUTION_STATUS"  VARCHAR2(50) DEFAULT 'PENDING',
    "ORGANIZATION_ID"   VARCHAR2(64),
    "DEPARTMENT_ID"     VARCHAR2(64),
    "PROJECT_ID"        VARCHAR2(64),
    "EXECUTOR_ID"       VARCHAR2(64),
    "EXECUTOR_NAME"     VARCHAR2(100),
    "REMARK"            VARCHAR2(500),
    "CREATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "CREATE_BY"         VARCHAR2(100),
    "UPDATE_BY"         VARCHAR2(100),
    "DEL_FLAG"          INTEGER DEFAULT 0,
    "TENANT_ID"         VARCHAR2(64),
    NOT CLUSTER PRIMARY KEY("EXECUTION_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_EXECUTION IS '预算执行表';

-- 1.2 预算控制规则表
CREATE TABLE "REDACTED"."TBL_BUDGET_CONTROL_RULE" (
    "RULE_ID"           VARCHAR2(64) NOT NULL,
    "RULE_CODE"         VARCHAR2(100),
    "RULE_NAME"         VARCHAR2(200),
    "RULE_TYPE"         VARCHAR2(50),
    "CONTROL_TYPE"      VARCHAR2(50),
    "CONTROL_LEVEL"     VARCHAR2(50),
    "THRESHOLD_VALUE"   NUMBER(20,2),
    "THRESHOLD_TYPE"    VARCHAR2(50),
    "ACTION_TYPE"       VARCHAR2(50),
    "IS_ENABLED"        NUMBER(1,0) DEFAULT 1,
    "PRIORITY"          INTEGER DEFAULT 0,
    "ORGANIZATION_ID"   VARCHAR2(64),
    "RULE_DESCRIPTION"  VARCHAR2(500),
    "CONTROL_CONDITIONS" CLOB,
    "NOTIFICATION_METHODS" VARCHAR2(200),
    "NOTIFICATION_USERS" VARCHAR2(500),
    "ALLOW_OVERRIDE"    NUMBER(1,0) DEFAULT 0,
    "CREATE_BY"         VARCHAR2(100),
    "CREATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATE_BY"         VARCHAR2(100),
    "UPDATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "DEL_FLAG"          INTEGER DEFAULT 0,
    NOT CLUSTER PRIMARY KEY("RULE_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_CONTROL_RULE IS '预算控制规则表';

-- 1.3 预算监控表
CREATE TABLE "REDACTED"."TBL_BUDGET_MONITOR" (
    "MONITOR_ID"        VARCHAR2(64) NOT NULL,
    "MONITOR_CODE"      VARCHAR2(100),
    "MONITOR_NAME"      VARCHAR2(200),
    "MONITOR_TYPE"      VARCHAR2(50),
    "BUDGET_ID"         VARCHAR2(64),
    "MONITOR_STATUS"    VARCHAR2(50) DEFAULT 'ACTIVE',
    "THRESHOLD_VALUE"   NUMBER(20,2),
    "CURRENT_VALUE"     NUMBER(20,2),
    "ALERT_LEVEL"       VARCHAR2(50),
    "ORGANIZATION_ID"   VARCHAR2(64),
    "LAST_CHECK_TIME"   TIMESTAMP(6),
    "CHECK_INTERVAL"    INTEGER DEFAULT 60,
    "CREATE_BY"         VARCHAR2(100),
    "CREATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATE_BY"         VARCHAR2(100),
    "UPDATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "DEL_FLAG"          INTEGER DEFAULT 0,
    "REMARK"            VARCHAR2(500),
    NOT CLUSTER PRIMARY KEY("MONITOR_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_MONITOR IS '预算监控表';

-- 1.4 预算警报表
CREATE TABLE "REDACTED"."TBL_BUDGET_ALERT" (
    "ALERT_ID"          VARCHAR2(64) NOT NULL,
    "ALERT_CODE"        VARCHAR2(100),
    "ALERT_NAME"        VARCHAR2(200),
    "ALERT_TYPE"        VARCHAR2(50),
    "ALERT_LEVEL"       VARCHAR2(50) DEFAULT 'MEDIUM',
    "BUDGET_ID"         VARCHAR2(64),
    "ORGANIZATION_ID"   VARCHAR2(64),
    "RULE_ID"           VARCHAR2(64),
    "ALERT_MESSAGE"     VARCHAR2(1000),
    "ALERT_DETAIL"      CLOB,
    "TRIGGER_VALUE"     NUMBER(20,2),
    "THRESHOLD_VALUE"   NUMBER(20,2),
    "ALERT_STATUS"      VARCHAR2(50) DEFAULT 'PENDING',
    "ACKNOWLEDGED_BY"   VARCHAR2(64),
    "ACKNOWLEDGED_TIME" TIMESTAMP(6),
    "ACKNOWLEDGED_NOTE" VARCHAR2(500),
    "RESOLVED_BY"       VARCHAR2(64),
    "RESOLVED_TIME"     TIMESTAMP(6),
    "RESOLVED_NOTE"     VARCHAR2(500),
    "ESCALATED_BY"      VARCHAR2(64),
    "ESCALATED_TIME"    TIMESTAMP(6),
    "ESCALATED_REASON"  VARCHAR2(500),
    "ESCALATED_TO"      VARCHAR2(64),
    "NOTIFICATION_METHOD" VARCHAR2(50),
    "IS_NOTIFIED"       NUMBER(1,0) DEFAULT 0,
    "NOTIFICATION_TIME" TIMESTAMP(6),
    "NOTIFICATION_RECEIVERS" VARCHAR2(500),
    "TRIGGER_TIME"      TIMESTAMP(6),
    "EXPIRE_TIME"       TIMESTAMP(6),
    "AUTO_CLOSE"        NUMBER(1,0) DEFAULT 0,
    "AUTO_CLOSE_HOURS"  INTEGER,
    "PRIORITY"          INTEGER DEFAULT 5,
    "COMPANY_ID"        VARCHAR2(64),
    "CREATE_BY"         VARCHAR2(100),
    "CREATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATE_BY"         VARCHAR2(100),
    "UPDATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "DEL_FLAG"          INTEGER DEFAULT 0,
    "REMARK"            VARCHAR2(500),
    NOT CLUSTER PRIMARY KEY("ALERT_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_ALERT IS '预算警报表';

-- 1.5 预算限额表
CREATE TABLE "REDACTED"."TBL_BUDGET_LIMIT" (
    "LIMIT_ID"          VARCHAR2(64) NOT NULL,
    "LIMIT_CODE"        VARCHAR2(100),
    "LIMIT_NAME"        VARCHAR2(200),
    "LIMIT_TYPE"        VARCHAR2(50),
    "BUDGET_ID"         VARCHAR2(64),
    "LIMIT_AMOUNT"      NUMBER(20,2) DEFAULT 0,
    "USED_AMOUNT"       NUMBER(20,2) DEFAULT 0,
    "REMAINING_AMOUNT"  NUMBER(20,2) DEFAULT 0,
    "LIMIT_STATUS"      VARCHAR2(50) DEFAULT 'ACTIVE',
    "ORGANIZATION_ID"   VARCHAR2(64),
    "DEPARTMENT_ID"     VARCHAR2(64),
    "EFFECTIVE_DATE"    DATE,
    "EXPIRY_DATE"       DATE,
    "CREATE_BY"         VARCHAR2(100),
    "CREATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATE_BY"         VARCHAR2(100),
    "UPDATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "DEL_FLAG"          INTEGER DEFAULT 0,
    "REMARK"            VARCHAR2(500),
    NOT CLUSTER PRIMARY KEY("LIMIT_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_LIMIT IS '预算限额表';

-- 1.6 预算配额表
CREATE TABLE "REDACTED"."TBL_BUDGET_QUOTA" (
    "QUOTA_ID"          VARCHAR2(64) NOT NULL,
    "QUOTA_CODE"        VARCHAR2(100),
    "QUOTA_NAME"        VARCHAR2(200),
    "BUDGET_ID"         VARCHAR2(64),
    "QUOTA_TYPE"        VARCHAR2(50),
    "QUOTA_AMOUNT"      NUMBER(20,2) DEFAULT 0,
    "USED_AMOUNT"       NUMBER(20,2) DEFAULT 0,
    "AVAILABLE_AMOUNT"  NUMBER(20,2) DEFAULT 0,
    "QUOTA_PERIOD"      VARCHAR2(50),
    "EFFECTIVE_DATE"    DATE,
    "EXPIRY_DATE"       DATE,
    "QUOTA_STATUS"      VARCHAR2(50) DEFAULT 'ACTIVE',
    "IS_ENABLED"        NUMBER(1,0) DEFAULT 1,
    "QUOTA_DESCRIPTION" VARCHAR2(500),
    "ALLOCATED_AMOUNT"  NUMBER(20,2) DEFAULT 0,
    "REMARK"            VARCHAR2(500),
    "CREATE_BY"         VARCHAR2(100),
    "CREATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATE_BY"         VARCHAR2(100),
    "UPDATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "DEL_FLAG"          INTEGER DEFAULT 0,
    NOT CLUSTER PRIMARY KEY("QUOTA_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_QUOTA IS '预算配额表';

-- 1.7 预算冻结表
CREATE TABLE "REDACTED"."TBL_BUDGET_FREEZE" (
    "FREEZE_ID"         VARCHAR2(64) NOT NULL,
    "FREEZE_CODE"       VARCHAR2(100),
    "FREEZE_NAME"       VARCHAR2(200),
    "BUDGET_ID"         VARCHAR2(64),
    "FREEZE_TYPE"       VARCHAR2(50),
    "FREEZE_AMOUNT"     NUMBER(20,2) DEFAULT 0,
    "FREEZE_REASON"     VARCHAR2(500),
    "FREEZE_STATUS"     VARCHAR2(50) DEFAULT 'FROZEN',
    "FREEZE_DATE"       DATE,
    "UNFREEZE_DATE"     DATE,
    "FREEZE_BY"         VARCHAR2(100),
    "UNFREEZE_BY"       VARCHAR2(100),
    "FREEZE_DESCRIPTION" VARCHAR2(500),
    "REMARK"            VARCHAR2(500),
    "CREATE_BY"         VARCHAR2(100),
    "CREATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATE_BY"         VARCHAR2(100),
    "UPDATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "DEL_FLAG"          INTEGER DEFAULT 0,
    NOT CLUSTER PRIMARY KEY("FREEZE_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_FREEZE IS '预算冻结表';

-- 1.8 预算保留表
CREATE TABLE "REDACTED"."TBL_BUDGET_RESERVE" (
    "RESERVE_ID"        VARCHAR2(64) NOT NULL,
    "RESERVE_CODE"      VARCHAR2(100),
    "RESERVE_NAME"      VARCHAR2(200),
    "BUDGET_ID"         VARCHAR2(64),
    "RESERVE_TYPE"      VARCHAR2(50),
    "RESERVE_AMOUNT"    NUMBER(20,2) DEFAULT 0,
    "USED_AMOUNT"       NUMBER(20,2) DEFAULT 0,
    "AVAILABLE_AMOUNT"  NUMBER(20,2) DEFAULT 0,
    "RESERVE_REASON"    VARCHAR2(500),
    "RESERVE_STATUS"    VARCHAR2(50) DEFAULT 'RESERVED',
    "RESERVE_DATE"      DATE,
    "EXPIRY_DATE"       DATE,
    "RESERVE_BY"        VARCHAR2(100),
    "RESERVE_DESCRIPTION" VARCHAR2(500),
    "APPROVE_REMARK"    VARCHAR2(500),
    "APPROVE_TIME"      TIMESTAMP(6),
    "EXECUTE_TIME"      TIMESTAMP(6),
    "REMARK"            VARCHAR2(500),
    "CREATE_BY"         VARCHAR2(100),
    "CREATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATE_BY"         VARCHAR2(100),
    "UPDATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "DEL_FLAG"          INTEGER DEFAULT 0,
    NOT CLUSTER PRIMARY KEY("RESERVE_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_RESERVE IS '预算保留表';

-- 1.9 预算转移表
CREATE TABLE "REDACTED"."TBL_BUDGET_TRANSFER" (
    "TRANSFER_ID"       VARCHAR2(64) NOT NULL,
    "TRANSFER_CODE"     VARCHAR2(100),
    "TRANSFER_NAME"     VARCHAR2(200),
    "SOURCE_BUDGET_ID"  VARCHAR2(64),
    "TARGET_BUDGET_ID"  VARCHAR2(64),
    "TRANSFER_TYPE"     VARCHAR2(50),
    "TRANSFER_AMOUNT"   NUMBER(20,2) DEFAULT 0,
    "TRANSFER_REASON"   VARCHAR2(500),
    "TRANSFER_STATUS"   VARCHAR2(50) DEFAULT 'DRAFT',
    "APPLY_DATE"        DATE,
    "TRANSFER_DATE"     DATE,
    "APPLY_BY"          VARCHAR2(100),
    "APPROVE_BY"        VARCHAR2(100),
    "APPROVE_DATE"      DATE,
    "TRANSFER_DESCRIPTION" VARCHAR2(500),
    "APPROVE_REMARK"    VARCHAR2(500),
    "APPROVE_TIME"      TIMESTAMP(6),
    "EXECUTE_TIME"      TIMESTAMP(6),
    "REMARK"            VARCHAR2(500),
    "CREATE_BY"         VARCHAR2(100),
    "CREATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATE_BY"         VARCHAR2(100),
    "UPDATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "DEL_FLAG"          INTEGER DEFAULT 0,
    NOT CLUSTER PRIMARY KEY("TRANSFER_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_TRANSFER IS '预算转移表';

-- 1.10 预算释放表
CREATE TABLE "REDACTED"."TBL_BUDGET_RELEASE" (
    "RELEASE_ID"            VARCHAR2(64) NOT NULL,
    "RELEASE_CODE"          VARCHAR2(100),
    "RELEASE_NAME"          VARCHAR2(200),
    "RELEASE_TITLE"         VARCHAR2(200),
    "BUDGET_ID"             VARCHAR2(64),
    "ORGANIZATION_ID"       VARCHAR2(64),
    "BUDGET_ACCOUNT_ID"     VARCHAR2(64),
    "RELEASE_TYPE"          VARCHAR2(50),
    "RELEASE_AMOUNT"        NUMBER(20,2) DEFAULT 0,
    "RELEASE_REASON"        VARCHAR2(500),
    "RELEASE_STATUS"        VARCHAR2(50) DEFAULT 'PENDING',
    "APPLY_DATE"            DATE,
    "PLANNED_RELEASE_DATE"  DATE,
    "RELEASE_DATE"          DATE,
    "APPLY_BY"              VARCHAR2(100),
    "APPROVE_BY"            VARCHAR2(100),
    "APPROVE_DATE"          DATE,
    "RELEASE_DESCRIPTION"   VARCHAR2(500),
    "APPROVE_REMARK"        VARCHAR2(500),
    "APPROVE_TIME"          TIMESTAMP(6),
    "EXECUTE_TIME"          TIMESTAMP(6),
    "REMARK"                VARCHAR2(500),
    "CREATE_BY"             VARCHAR2(100),
    "CREATE_TIME"           TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATE_BY"             VARCHAR2(100),
    "UPDATE_TIME"           TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "DEL_FLAG"              INTEGER DEFAULT 0,
    NOT CLUSTER PRIMARY KEY("RELEASE_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_RELEASE IS '预算释放表';
COMMENT ON COLUMN REDACTED.TBL_BUDGET_RELEASE."RELEASE_TITLE" IS '释放标题';
COMMENT ON COLUMN REDACTED.TBL_BUDGET_RELEASE."ORGANIZATION_ID" IS '组织单元ID';
COMMENT ON COLUMN REDACTED.TBL_BUDGET_RELEASE."BUDGET_ACCOUNT_ID" IS '预算科目ID';
COMMENT ON COLUMN REDACTED.TBL_BUDGET_RELEASE."PLANNED_RELEASE_DATE" IS '计划释放日期';



-- ============================================================
-- 模块2: 预算分析管理 (budgetAnalysis)
-- ============================================================

-- 2.1 预算对比分析表
CREATE TABLE "REDACTED"."BUDGET_COMPARISON_ANALYSIS" (
    "ID"                VARCHAR2(64) NOT NULL,
    "ANALYSIS_CODE"     VARCHAR2(100),
    "ANALYSIS_NAME"     VARCHAR2(200),
    "COMPARISON_TYPE"   VARCHAR2(50),
    "BASE_BUDGET_ID"    VARCHAR2(64),
    "BASE_BUDGET_YEAR"  INTEGER,
    "BASE_BUDGET_PERIOD" VARCHAR2(50),
    "COMPARE_BUDGET_ID" VARCHAR2(64),
    "COMPARE_BUDGET_YEAR" INTEGER,
    "COMPARE_BUDGET_PERIOD" VARCHAR2(50),
    "ORGANIZATION_ID"   VARCHAR2(64),
    "ORGANIZATION_NAME" VARCHAR2(200),
    "ACCOUNT_ID"        VARCHAR2(64),
    "ACCOUNT_NAME"      VARCHAR2(200),
    "BASE_AMOUNT"       NUMBER(20,2),
    "COMPARE_AMOUNT"    NUMBER(20,2),
    "DIFFERENCE_AMOUNT" NUMBER(20,2),
    "DIFFERENCE_RATE"   NUMBER(10,2),
    "COMPARISON_RESULT" VARCHAR2(50),
    "ANALYSIS_DESCRIPTION" VARCHAR2(1000),
    "DIFFERENCE_REASON" VARCHAR2(1000),
    "IMPROVEMENT_SUGGESTION" VARCHAR2(1000),
    "ANALYSIS_RESULT"   VARCHAR2(1000),
    "ANALYSIS_DIMENSION" VARCHAR2(50),
    "ANALYSIS_STATUS"   VARCHAR2(50) DEFAULT 'draft',
    "ANALYZED_BY"       VARCHAR2(100),
    "ANALYZED_TIME"     TIMESTAMP(6),
    "REVIEWED_BY"       VARCHAR2(100),
    "REVIEWED_TIME"     TIMESTAMP(6),
    "REMARK"            VARCHAR2(500),
    "CREATE_BY"         VARCHAR2(100),
    "CREATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATE_BY"         VARCHAR2(100),
    "UPDATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "DEL_FLAG"          INTEGER DEFAULT 0,
    NOT CLUSTER PRIMARY KEY("ID")
);
COMMENT ON TABLE REDACTED.BUDGET_COMPARISON_ANALYSIS IS '预算对比分析表';

-- 2.2 预算差异分析表
CREATE TABLE "REDACTED"."BUDGET_VARIANCE_ANALYSIS" (
    "ID"                VARCHAR2(64) NOT NULL,
