    "BUDGET_ID"         VARCHAR2(64),
    "BUDGET_YEAR"       INTEGER,
    "BUDGET_PERIOD"     VARCHAR2(50),
    "ORGANIZATION_ID"   VARCHAR2(64),
    "ORGANIZATION_NAME" VARCHAR2(200),
    "ACCOUNT_ID"        VARCHAR2(64),
    "ACCOUNT_NAME"      VARCHAR2(200),
    "BUDGET_AMOUNT"     NUMBER(20,2),
    "ACTUAL_AMOUNT"     NUMBER(20,2),
    "VARIANCE_AMOUNT"   NUMBER(20,2),
    "VARIANCE_RATE"     NUMBER(10,2),
    "VARIANCE_TYPE"     VARCHAR2(50),
    "VARIANCE_REASON"   VARCHAR2(1000),
    "ANALYSIS_DESCRIPTION" VARCHAR2(1000),
    "IMPROVEMENT_MEASURES" VARCHAR2(1000),
    "ANALYSIS_RESULT"   VARCHAR2(1000),
    "ANALYSIS_DIMENSION" VARCHAR2(50),
    "ANALYSIS_STATUS"   VARCHAR2(50) DEFAULT 'draft',
    "ANALYZED_BY"       VARCHAR2(100),
    "ANALYZED_TIME"     TIMESTAMP(6),
    "REVIEWED_BY"       VARCHAR2(100),
    "REVIEWED_TIME"     TIMESTAMP(6),
    "REMARK"            VARCHAR2(500),
    "CREATE_BY"         VARCHAR2(100),
    "CREATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATE_BY"         VARCHAR2(100),
    "UPDATE_TIME"       TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "DEL_FLAG"          INTEGER DEFAULT 0,
    NOT CLUSTER PRIMARY KEY("ID")
);
COMMENT ON TABLE REDACTED.BUDGET_VARIANCE_ANALYSIS IS '预算差异分析表';

-- 2.3 预算趋势分析表
CREATE TABLE "REDACTED"."BUDGET_TREND_ANALYSIS" (
    "ID"                VARCHAR2(64) NOT NULL,
    "ANALYSIS_CODE"     VARCHAR2(100),
