    "DEL_FLAG"          INTEGER DEFAULT 0,
    NOT CLUSTER PRIMARY KEY("ID")
);
COMMENT ON TABLE REDACTED.BUDGET_TREND_ANALYSIS IS '预算趋势分析表';


-- 2.4 预算预测分析表
CREATE TABLE "REDACTED"."BUDGET_FORECAST_ANALYSIS" (
    "ID"                VARCHAR2(64) NOT NULL,
