-- ============================================================
-- 模块4: budgetSystem (预算系统管理) - 建表语句
-- ============================================================

-- 4.1 预算模型表
CREATE TABLE "REDACTED"."TBL_BUDGET_MODEL" (
    "MODEL_ID"              VARCHAR2(64) NOT NULL,
    "MODEL_NAME"            VARCHAR2(200),
    "MODEL_CODE"            VARCHAR2(100),
    "MODEL_TYPE"            VARCHAR2(50),
    "MODEL_STATUS"          VARCHAR2(50) DEFAULT 'DRAFT',
    "APPLICABLE_SCOPE"      VARCHAR2(500),
    "IS_ENABLED"            INTEGER DEFAULT 1,
    "SORT_ORDER"            INTEGER DEFAULT 0,
    "COPIED_FROM"           VARCHAR2(64),
    "BUDGET_CYCLE"          VARCHAR2(50),
    "DESCRIPTION"           VARCHAR2(1000),
    "MODEL_DESCRIPTION"     CLOB,
    "CONFIG_PARAMETERS"     CLOB,
    "CALCULATION_RULES"     CLOB,
    "VERSION"               VARCHAR2(50),
    "VERSION_NUM"           VARCHAR2(50),
    "IS_CURRENT_VERSION"    INTEGER DEFAULT 1,
    "FORMULA"               CLOB,
    "DIMENSIONS"            CLOB,
    "STATUS"                VARCHAR2(50),
    "CREATOR_ID"            VARCHAR2(64),
    "CREATOR_NAME"          VARCHAR2(100),
    "CREATE_TIME"           TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATER_ID"            VARCHAR2(64),
    "UPDATER_NAME"          VARCHAR2(100),
    "UPDATE_TIME"           TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "IS_DELETED"            INTEGER DEFAULT 0,
    "COMPANY_ID"            VARCHAR2(64),
    "COMPANY_NAME"          VARCHAR2(200),
    NOT CLUSTER PRIMARY KEY("MODEL_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_MODEL IS '预算模型表';

-- 4.2 预算维度表
CREATE TABLE "REDACTED"."TBL_BUDGET_DIMENSION" (
    "DIMENSION_ID"          VARCHAR2(64) NOT NULL,
    "DIMENSION_NAME"        VARCHAR2(200),
    "DIMENSION_CODE"        VARCHAR2(100),
    "DIMENSION_TYPE"        VARCHAR2(50),
    "PARENT_ID"             VARCHAR2(64),
    "SORT_ORDER"            INTEGER DEFAULT 0,
    "IS_REQUIRED"           INTEGER DEFAULT 0,
    "DIMENSION_DESCRIPTION" VARCHAR2(1000),
    "CREATOR_ID"            VARCHAR2(64),
    "CREATOR_NAME"          VARCHAR2(100),
    "CREATE_TIME"           TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATER_ID"            VARCHAR2(64),
    "UPDATER_NAME"          VARCHAR2(100),
    "UPDATE_TIME"           TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "IS_ACTIVE"             INTEGER DEFAULT 1,
    "IS_DELETED"            INTEGER DEFAULT 0,
    "COMPANY_ID"            VARCHAR2(64),
    "COMPANY_NAME"          VARCHAR2(200),
    NOT CLUSTER PRIMARY KEY("DIMENSION_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_DIMENSION IS '预算维度表';

-- 4.3 预算指标表
CREATE TABLE "REDACTED"."TBL_BUDGET_INDICATOR" (
    "INDICATOR_ID"          VARCHAR2(64) NOT NULL,
    "INDICATOR_CODE"        VARCHAR2(100),
    "INDICATOR_NAME"        VARCHAR2(200),
    "INDICATOR_TYPE"        VARCHAR2(50),
    "DATA_TYPE"             VARCHAR2(50),
    "UNIT"                  VARCHAR2(50),
    "DECIMAL_PLACES"        INTEGER DEFAULT 2,
    "FORMULA"               CLOB,
    "SUMMARY_METHOD"        VARCHAR2(50),
    "DEFAULT_VALUE"         NUMBER(20,2),
    "MIN_VALUE"             NUMBER(20,2),
    "MAX_VALUE"             NUMBER(20,2),
    "IS_REQUIRED"           INTEGER DEFAULT 0,
    "IS_CALCULATED"         INTEGER DEFAULT 0,
    "IS_ENABLED"            INTEGER DEFAULT 1,
    "DESCRIPTION"           VARCHAR2(1000),
    "REMARK"                VARCHAR2(500),
    "CREATOR_ID"            VARCHAR2(64),
    "CREATOR_NAME"          VARCHAR2(100),
    "CREATE_TIME"           TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "UPDATER_ID"            VARCHAR2(64),
    "UPDATER_NAME"          VARCHAR2(100),
    "UPDATE_TIME"           TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP,
    "IS_DELETED"            INTEGER DEFAULT 0,
    "COMPANY_ID"            VARCHAR2(64),
    "COMPANY_NAME"          VARCHAR2(200),
    NOT CLUSTER PRIMARY KEY("INDICATOR_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_INDICATOR IS '预算指标表';

-- 4.4 预算组织体系表
CREATE TABLE "REDACTED"."TBL_BUDGET_ORGANIZATION_STRUCTURE" (
