    "IS_DELETED"            INTEGER DEFAULT 0,
    "COMPANY_ID"            VARCHAR2(64),
    "COMPANY_NAME"          VARCHAR2(200),
    NOT CLUSTER PRIMARY KEY("STRUCTURE_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_ORGANIZATION_STRUCTURE IS '预算组织体系表';


