    NOT CLUSTER PRIMARY KEY("PERMISSION_ID")
);
COMMENT ON TABLE REDACTED.TBL_BUDGET_PERMISSION IS '预算权限配置表';

-- 4.6 系统配置表
CREATE TABLE "REDACTED"."TBL_BUDGET_SYSTEM_CONFIG" (
    "CONFIG_ID"             VARCHAR2(64) NOT NULL,
